function myInstanceof(obj, Ctor) {
  if (obj === null || (typeof obj !== "object" && typeof obj !== "function")) return false;
  for (let p = Object.getPrototypeOf(obj); p !== null; p = Object.getPrototypeOf(p)) {
    if (p === Ctor.prototype) return true;
  }
  return false;
}

function Fruit() {}
function Apple() {}
Apple.prototype = Object.create(Fruit.prototype);

console.log(myInstanceof(new Apple(), Fruit));
console.log(myInstanceof(Apple.prototype, Apple));
console.log(myInstanceof(Apple, Function));
console.log(myInstanceof("apple", Object));
